function Drawing({ name, color, size }: { name: string; color: string; size: number }) {
  return (
    <Svg width={size} height={size} viewBox="0 0 24 24" fill="none">
      {(DRAWINGS[name] ?? DRAWINGS.services).map((p, i) => {
        const c = p.c === "accent" ? ACCENT : p.c ?? color;
        const stroke = { stroke: c, strokeWidth: p.w ?? STROKE, strokeLinecap: "round" as const, strokeLinejoin: "round" as const };
        if (p.k === "line") return <Path key={i} d={p.d} fill="none" {...stroke} strokeOpacity={p.o ?? 1} />;
        if (p.k === "shape") return <Path key={i} d={p.d} fill={color} fillOpacity={DUOTONE} {...stroke} />;
        return <Path key={i} d={p.d} fill={c} fillOpacity={p.fo ?? 1} {...(p.s ? stroke : {})} />;
      })}
    </Svg>
  );
}

type IconProps = { color: string; size?: number };

// ─── Map controls ────────────────────────────────────────────────────────────

/** Map layers: three map sheets in perspective, the top one in Navigo orange. */
export function MapLayersIcon({ color, size = 22 }: IconProps) {
  return <Drawing name="map-layers" color={color} size={size} />;
}

/** Report: a megaphone in the icon colour, its sound waves in Navigo orange. */
export function ReportIcon({ color, size = 22 }: IconProps) {
  return <Drawing name="report" color={color} size={size} />;
}

// ─── Place categories (QUICK_CATEGORIES) ─────────────────────────────────────

export type PlaceCategoryKey = "restaurant" | "cafe" | "gas" | "hospital" | "parking" | "store" | "pharmacy" | "atm" | "hotel" | "mall" | "shopping" | "attraction" | "park" | "entertainment" | "nightlife" | "sport" | "school" | "worship" | "government";
const PLACE: Record<PlaceCategoryKey, string> = {"restaurant":"restaurant","cafe":"cafe","gas":"gas","hospital":"hospital","parking":"parking","store":"store","pharmacy":"pharmacy","atm":"atm","hotel":"lodging","mall":"mall","shopping":"store","attraction":"attraction","park":"park","entertainment":"entertainment","nightlife":"nightlife","sport":"sport","school":"education","worship":"worship","government":"government"};

/** Duotone icon for a quick-search place category. */
export function PlaceCategoryIcon({ category, color, size = 16 }: IconProps & { category: PlaceCategoryKey }) {
  return <Drawing name={PLACE[category]} color={color} size={size} />;
}

