/** Each stop type's badge colour (the map's stop markers and StopTypeBadge). */
export const STOP_COLORS: Record<StopCategory, string> = {"rail":"#16A34A","metro":"#7C3AED","brt":"#DC2626","ferry":"#0284C7","tram":"#DB2777","airport":"#334155","cable":"#65A30D","terminal":"#EA580C","bus":"#2563EB"};

/** Glyph for a stop type. White on a coloured badge by default. */
